import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    k = int(input_data[1])

    if n * (n - 1) // 2 < k * n:
        print("-1")
        return

    matches = []
    wins_count = [0] * (n + 1)

    current_team = 1
    offset = 1

    while len(matches) < k * n:
        if wins_count[current_team] < k:
            opponent = (current_team + offset - 1) % n + 1
            if opponent == current_team:
                offset += 1
                continue

            if wins_count[opponent] < k:
                matches.append((current_team, opponent))
                wins_count[current_team] += 1
            else:
                offset += 1
                continue
        else:
            current_team += 1
            if current_team > n:
                current_team = 1
            offset = 1

    print(len(matches))
    for a, b in matches:
        print(f"{a} {b}")

if __name__ == "__main__":
    solve()
